<script setup>import { ArrowDownRight, ArrowUpRight } from 'lucide-vue-next'; defineProps({ title: String, value: [String, Number], icon: [Object, Function], tone: String, trend: String, direction: { type: String, default: 'up' } }); defineEmits(['click'])</script>
<template><button class="stat-card" @click="$emit('click')"><span class="stat-icon" :class="tone"><component :is="icon" :size="20" /></span><span class="stat-body"><small>{{ title }}</small><strong>{{ value }}</strong></span><span v-if="trend" class="stat-trend" :class="direction"><component :is="direction === 'up' ? ArrowUpRight : ArrowDownRight" :size="14" />{{ trend }}</span></button></template>
